add('sample_hint', 'Try a sample code', 'Prueba un código de ejemplo', 'Probiere einen Beispielcode', 'Essayez un code d’exemple', 'Prova un codice di esempio', 'Experimente um código de exemplo', 'कोई नमूना कोड आज़माएँ', 'Coba kode contoh')

add('pro_pending', 'Your purchase is pending. Pro unlocks as soon as it completes.', 'Tu compra está pendiente. Pro se desbloquea en cuanto se complete.', 'Dein Kauf ist ausstehend. Pro wird freigeschaltet, sobald er abgeschlossen ist.', 'Votre achat est en attente. Pro se débloque dès qu’il est finalisé.', 'Il tuo acquisto è in sospeso. Pro si sblocca appena viene completato.', 'A sua compra está pendente. O Pro desbloqueia assim que for concluída.', 'आपकी खरीद लंबित है। पूरी होते ही प्रो अनलॉक हो जाएगा।', 'Pembelian Anda tertunda. Pro terbuka begitu selesai.')
add('open_failed', 'No app on this phone can open that.', 'Ninguna app de este móvil puede abrir eso.', 'Keine App auf diesem Handy kann das öffnen.', 'Aucune appli de ce téléphone ne peut ouvrir cela.', 'Nessuna app su questo telefono può aprirlo.', 'Nenhuma app neste telemóvel consegue abrir isso.', 'इस फ़ोन का कोई ऐप इसे नहीं खोल सकता।', 'Tidak ada aplikasi di ponsel ini yang bisa membukanya.')
add('save_failed', 'Could not save the picture.', 'No se pudo guardar la imagen.', 'Das Bild konnte nicht gespeichert werden.', 'Impossible d’enregistrer l’image.', 'Impossibile salvare l’immagine.', 'Não foi possível guardar a imagem.', 'तस्वीर सेव नहीं हो सकी।', 'Gambar tidak dapat disimpan.')
add('cam_unavailable', 'The camera could not start.', 'No se pudo iniciar la cámara.', 'Die Kamera konnte nicht gestartet werden.', 'La caméra n’a pas pu démarrer.', 'Impossibile avviare la fotocamera.', 'Não foi possível iniciar a câmara.', 'कैमरा शुरू नहीं हो सका।', 'Kamera tidak dapat dimulai.')
